package ru.truetv.launcher;
import android.app.*;
import android.content.*;
import android.content.res.Configuration;
import android.os.*;
import android.provider.DocumentsContract;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import android.widget.*;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;
/** Real folder/TXT buttons and stable frames, on own disposable VM fixture only. */
public final class FileVisualCheck extends Instrumentation {
 private Context c;private int checks;private StringBuilder output=new StringBuilder();private File fixture;private FileActivity a;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void check(boolean b,String name){output.append(b?"PASS ":"FAIL ").append(name).append('\n');checks++;if(!b)throw new AssertionError(name);}
 private void main(Runnable r){runOnMainSync(r);waitForIdleSync();}
 private Object field(Object obj,String name)throws Exception{Field f=obj.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(obj);}
 private void invoke(String name,Class<?> type,Object value){try{Method m=type==null?a.getClass().getDeclaredMethod(name):a.getClass().getDeclaredMethod(name,type);m.setAccessible(true);if(type==null)m.invoke(a);else m.invoke(a,value);}catch(Exception e){throw new AssertionError(e);}}
 @SuppressWarnings("unchecked")private List<FileStore.Node> entries()throws Exception{return (List<FileStore.Node>)field(a,"entries");}
 private AccessibilityNodeInfo find(AccessibilityNodeInfo node,String className){if(node==null)return null;if(className.contentEquals(node.getClassName()))return node;for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo found=find(node.getChild(i),className);if(found!=null)return found;}return null;}
 private void stable()throws Exception{VmWindows.ready(this);Thread.sleep(600);try{getUiAutomation().waitForIdle(180,3000);}catch(java.util.concurrent.TimeoutException ignored){}}
 private void shot(String name)throws Exception{stable();android.graphics.Bitmap screen=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(c.getExternalFilesDir(null),name))){screen.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}screen.recycle();}
 private AccessibilityNodeInfo saveButton(AccessibilityNodeInfo root){if(root==null)return null;for(String label:new String[]{"Сохранить","Save"})for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(label))if(n.isClickable())return n;return null;}
 private void create(int button,String name,boolean directory)throws Exception {
  LinearLayout actions=(LinearLayout)field(a,"folderActions");main(()->actions.getChildAt(button).performClick());AccessibilityNodeInfo input=null,save=null;long deadline=SystemClock.uptimeMillis()+12000;
  while(SystemClock.uptimeMillis()<deadline){VmWindows.clear(this);ArrayList<AccessibilityNodeInfo> roots=new ArrayList<>();roots.add(getUiAutomation().getRootInActiveWindow());for(android.view.accessibility.AccessibilityWindowInfo window:getUiAutomation().getWindows())roots.add(window.getRoot());for(AccessibilityNodeInfo root:roots){AccessibilityNodeInfo candidate=find(root,"android.widget.EditText"),confirm=saveButton(root);if(candidate!=null&&"ru.truetv.launcher".contentEquals(candidate.getPackageName())&&confirm!=null){input=candidate;save=confirm;break;}}if(input!=null)break;Thread.sleep(120);}
  if(input==null){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();output.append("Active root: ").append(root==null?"null":root.getPackageName()+" / "+root.getClassName()).append(" Activity lifecycle finishing=").append(a.isFinishing()).append('\n');shot("212-create-failure.png");}
  check(input!=null,"own edit dialog for "+name);if(directory)check(input.getText()!=null&&!input.getText().toString().isEmpty(),"new-folder name is prefilled");Bundle args=new Bundle();args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,name);check(input.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,args),"entered new name "+name);check(save.performAction(AccessibilityNodeInfo.ACTION_CLICK),"confirmed create "+name);File file=new File(fixture,name+(directory?"":".txt"));long until=SystemClock.uptimeMillis()+20000;while(!file.exists()&&SystemClock.uptimeMillis()<until)Thread.sleep(100);check(directory?file.isDirectory():file.isFile()&&file.length()==0,"created correct object on storage "+file.getName());stable();
 }

 private ChoiceDialog openSort()throws Exception {final ChoiceDialog[] result={null};main(()->{try{((LinearLayout)field(a,"folderActions")).getChildAt(6).requestFocusFromTouch();Method m=a.getClass().getDeclaredMethod("sortMenu");m.setAccessible(true);result[0]=(ChoiceDialog)m.invoke(a);}catch(Exception e){throw new AssertionError(e);}});stable();return result[0];}
 private void waitFirst(String name)throws Exception {long deadline=SystemClock.uptimeMillis()+15000;while((entries().isEmpty()||!entries().get(0).file.getName().equals(name))&&SystemClock.uptimeMillis()<deadline)Thread.sleep(80);waitForIdleSync();check(!entries().isEmpty()&&entries().get(0).file.getName().equals(name),"file order starts with "+name);}
 private void chooseSort(ChoiceDialog dialog,int index)throws Exception {List<FileStore.Node> previous=entries();main(()->dialog.list.performItemClick(dialog.list.getAdapter().getView(index,null,dialog.list),index,index));awaitReload(previous);}
 private void awaitReload(List<FileStore.Node> previous)throws Exception {long until=SystemClock.uptimeMillis()+15000;while(entries()==previous&&SystemClock.uptimeMillis()<until)Thread.sleep(80);waitForIdleSync();if(entries()==previous)throw new AssertionError("Load callback did not publish new entries");}
 private void reload()throws Exception {List<FileStore.Node> previous=entries();main(()->invoke("load",null,null));awaitReload(previous);}
 private void sorting()throws Exception {
  String[] names={"Документы","Музыка","Архив.zip","Книга.pdf","Заметки.txt","Новая папка","Новый текст.txt"};for(int i=0;i<names.length;i++)check(new File(fixture,names[i]).setLastModified((i+1)*100000L),"stored distinct mtime for "+names[i]);
  reload();waitFirst("Новый текст.txt");check(((Integer)field(a,"sortOrder"))==0,"fresh install defaults to newest first");check(entries().get(1).file.getName().equals("Новая папка")&&entries().get(2).file.getName().equals("Заметки.txt"),"date order interleaves files and folders");
  FileStore.Node selected=entries().get(0);main(()->invoke("toggle",FileStore.Node.class,selected));ChoiceDialog dialog=openSort();check(dialog.list.getCheckedItemPosition()==0&&dialog.list.getSelectedItemPosition()==0,"Sort opens with current native radio and cursor");shot("sort216-final.png");chooseSort(dialog,1);waitFirst("Документы");check(((Set<?>)field(a,"selected")).contains(selected.id),"sort preserves selection by document identity");check(((ListView)field(a,"list")).getHeaderViewsCount()==1,"Back stays above sorted documents");check(((LinearLayout)field(a,"folderActions")).getChildAt(6).hasFocus(),"sort returns focus to right-hand command");
  dialog=openSort();check(dialog.list.getCheckedItemPosition()==1,"selected oldest option shown on reopen");final ChoiceDialog cancel=dialog;main(cancel.cancel::performClick);check(c.getSharedPreferences("file_view",0).getInt("sort_order",-1)==1,"Cancel leaves saved order unchanged");
  dialog=openSort();chooseSort(dialog,2);stable();for(int i=1;i<entries().size();i++)check(entries().get(i-1).file.getName().compareToIgnoreCase(entries().get(i).file.getName())<=0,"native name ascending "+i);
  dialog=openSort();chooseSort(dialog,3);stable();for(int i=1;i<entries().size();i++)check(entries().get(i-1).file.getName().compareToIgnoreCase(entries().get(i).file.getName())>=0,"native name descending "+i);
  dialog=openSort();chooseSort(dialog,1);waitFirst("Документы");main(a::finish);a=(FileActivity)startActivitySync(new Intent(c,FileActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra(DocumentsContract.EXTRA_INITIAL_URI,FileStore.get(c).uri(FileStore.get(c).identify(fixture))));waitFirst("Документы");check(((Integer)field(a,"sortOrder"))==1,"sort preference survives activity restart");
  dialog=openSort();chooseSort(dialog,0);waitFirst("Новый текст.txt");main(()->{EditText q=(EditText)fieldSafe("query");q.setText("txt");invoke("load",null,null);});long until=SystemClock.uptimeMillis()+15000;while(entries().size()!=2&&SystemClock.uptimeMillis()<until)Thread.sleep(80);check(entries().size()==2&&entries().get(0).file.getName().equals("Новый текст.txt"),"search results retain newest-first order");main(()->{((EditText)fieldSafe("query")).setText("");invoke("load",null,null);});waitFirst("Новый текст.txt");
 }
 private Object fieldSafe(String name){try{return field(a,name);}catch(Exception e){throw new AssertionError(e);}}
 public void onStart(){c=getTargetContext();android.accessibilityservice.AccessibilityServiceInfo service=getUiAutomation().getServiceInfo();service.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS|android.accessibilityservice.AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;getUiAutomation().setServiceInfo(service);Bundle done=new Bundle();try{
  check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("Android SDK"),"disposable VM guard");VmWindows.prepare(this);c.getSharedPreferences("file_view",0).edit().clear().commit();
  fixture=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS),"Проверка файлов "+System.currentTimeMillis());check(fixture.mkdirs(),"created own fixture");new File(fixture,"Документы").mkdir();new File(fixture,"Музыка").mkdir();for(String name:new String[]{"Заметки.txt","Книга.pdf","Архив.zip"})try(FileOutputStream out=new FileOutputStream(new File(fixture,name))){out.write("Тест".getBytes("UTF-8"));}
  a=(FileActivity)startActivitySync(new Intent(c,FileActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra(DocumentsContract.EXTRA_INITIAL_URI,FileStore.get(c).uri(FileStore.get(c).identify(fixture))));long deadline=SystemClock.uptimeMillis()+20000;while(entries().size()<5&&SystemClock.uptimeMillis()<deadline)Thread.sleep(100);waitForIdleSync();check(((TextView)field(a,"folderTitle")).getText().toString().equals(fixture.getName()),"native folder header preserves real filename");
  for(String language:new String[]{"ru","en","de"}){Configuration test=new Configuration(c.getResources().getConfiguration());test.setLocale(new Locale(language));Context localized=c.createConfigurationContext(test);check(Ui.word(localized,"Русский","English").equals(language.equals("ru")?"Русский":"English"),"system language mapping "+language);check(localized.getString(R.string.file_manager_name).startsWith(language.equals("ru")?"Файлы":"Files"),"system picker resource language "+language);}
  LinearLayout panel=(LinearLayout)((View)field(a,"list")).getParent();ViewGroup columns=(ViewGroup)panel.getParent();check(columns.getChildCount()==5&&columns.getChildAt(1).getWidth()==Ui.dp(c,1)&&columns.getChildAt(3).getWidth()==Ui.dp(c,1),"two full-height vertical column separators");LinearLayout actionIcons=(LinearLayout)field(a,"folderActions");int[] treePoint=new int[2],filePoint=new int[2],actionPoint=new int[2];((View)field(a,"tree")).getLocationOnScreen(treePoint);((View)field(a,"list")).getLocationOnScreen(filePoint);actionIcons.getLocationOnScreen(actionPoint);check(treePoint[0]<filePoint[0]&&filePoint[0]<actionPoint[0],"columns are tree, files, folder actions");check(((ListView)field(a,"list")).getHeaderViewsCount()==1,"folder content starts with Back");for(int i=0;i<actionIcons.getChildCount();i++)check(((TextView)actionIcons.getChildAt(i)).getCompoundDrawablesRelative()[0]!=null,"folder action has matching vector icon "+i);
  create(0,"Новая папка",true);create(1,"Новый текст",false);long updated=SystemClock.uptimeMillis()+20000;while(entries().size()<7&&SystemClock.uptimeMillis()<updated)Thread.sleep(100);waitForIdleSync();check(FileCore.mime("Новый текст.txt").equals("text/plain"),"created TXT has text MIME");
  for(FileStore.Node n:entries())if(n.file.getName().equals("Документы")||n.file.getName().equals("Заметки.txt"))main(()->invoke("toggle",FileStore.Node.class,n));TextView count=(TextView)field(a,"selectedCount");check(count.getTextSize()>=22*c.getResources().getDisplayMetrics().scaledDensity&&count.getParent()==((View)field(a,"folderTitle")).getParent(),"large N/total counter shares folder title row");check(((LinearLayout)field(a,"folderActions")).getShowDividers()==LinearLayout.SHOW_DIVIDER_MIDDLE,"folder actions have row separators");Button menu=(Button)field(a,"more");main(menu::requestFocusFromTouch);shot("files216-final.png");check(menu.hasFocus(),"labelled Menu focus captured");
  LinearLayout actions=(LinearLayout)field(a,"folderActions");main(()->actions.getChildAt(4).performClick());for(FileStore.Node n:entries())if(n.file.getName().equals("Заметки.txt"))main(()->invoke("menu",FileStore.Node.class,n));shot("file-menu216-final.png");Field active=ActionSheet.class.getDeclaredField("active");active.setAccessible(true);ActionSheet sheet=(ActionSheet)((java.lang.ref.WeakReference<?>)active.get(null)).get();main(sheet.dialog::dismiss);for(FileStore.Node n:entries())if(n.file.getName().equals("Документы"))main(()->invoke("menu",FileStore.Node.class,n));shot("folder-menu216-final.png");sheet=(ActionSheet)((java.lang.ref.WeakReference<?>)active.get(null)).get();main(sheet.dialog::dismiss);ListView tree=(ListView)field(a,"tree"),fileList=(ListView)field(a,"list");main(()->{tree.requestFocusFromTouch();tree.setSelection(2);});stable();View selectedTree=tree.getSelectedView();check(selectedTree!=null&&selectedTree.getBackground()==null&&((TextView)((ViewGroup)selectedTree).getChildAt(0)).getMaxLines()==2,"tree frame leaves connector lane clear and titles wrap");check(tree.getWidth()<fileList.getWidth()*.34f,"tree column narrowed to free file area");shot("tree216-final.png");
  sorting();
  done.putString("report",output+"Checks="+checks);done.putBoolean("passed",true);
 }catch(Throwable e){StringWriter trace=new StringWriter();e.printStackTrace(new PrintWriter(trace));done.putString("report",output.toString()+trace);done.putBoolean("passed",false);}finally{try{if(a!=null)main(a::finish);if(fixture!=null)FileCore.erase(fixture,FileCore.NEVER);FileStore.get(c).purgeMissing();}catch(Exception ignored){}}finish(done.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,done);}
}
